1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's locality (region) from their postcode, falling back to their city.
7	 *
8	 * <p>The postcode is matched against fixed 4-digit ranges (NSW 2000-2099, VIC 3000-3099,
9	 * QLD 4000-4099). When the postcode is absent or falls in no known range, the region is looked up
10	 * in a fixed city-to-region table that pins Sydney -&gt; NSW, Melbourne -&gt; VIC and
11	 * Brisbane -&gt; QLD. Anything that matches neither derives the locality {@code "UNKNOWN"}.
12	 */
13	public final class LocalityLookup {
14	
15	    /** City -&gt; canonical region; anything not listed derives locality {@code "UNKNOWN"}. */
16	    private static final Map<String, String> CITY_REGION =
17	        Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
18	
19	    /** Region -&gt; inclusive 4-digit postcode range {low, high}. */
20	    private static final Map<String, int[]> REGION_POSTCODES =
21	        Map.of("NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099},
22	            "QLD", new int[] {4000, 4099});
23	
24	    private LocalityLookup() {
25	    }
26	
27	    /**
28	     * Returns an owner's locality from their region-and-hash customer code, falling back to the
29	     * postcode-and-city derivation when no customer code is present.
30	     *
31	     * <p>Since an owner's {@code customerCode} is formatted {@code <REGION>-<HASH8>}, the locality is
32	     * the region component that precedes the first {@code '-'}. Owners without a customer code (for
33	     * example seed data that predates identity assignment) fall back to
34	     * {@link #forPostcodeAndCity(String, String)}.
35	     *
36	     * @param customerCode the owner's region-and-hash customer code, or {@code null}
37	     * @param postcode the owner's stored postcode, or {@code null} (used only for the fallback)
38	     * @param city the owner's stored city, or {@code null} (used only for the fallback)
39	     * @return the region component of the customer code, or the postcode-and-city fallback
40	     */
41	    public static String forCustomerCode(String customerCode, String postcode, String city) {
42	        if (customerCode != null) {
43	            int separator = customerCode.indexOf('-');
44	            if (separator > 0) {
45	                return customerCode.substring(0, separator);
46	            }
47	        }
48	        return forPostcodeAndCity(postcode, city);
49	    }
50	
51	    /**
52	     * Returns the canonical region for the given postcode and city, preferring the postcode.
53	     *
54	     * <p>The postcode is looked up by range first; only when it is absent or in no known range does
55	     * the city-to-region table decide. This returns the same region for known cities but
56	     * disambiguates cities that share a name.
57	     *
58	     * @param postcode the owner's stored postcode, or {@code null}
59	     * @param city the owner's stored city, or {@code null}
60	     * @return the canonical region string, or {@code "UNKNOWN"} when neither postcode nor city maps
61	     */
62	    public static String forPostcodeAndCity(String postcode, String city) {
63	        String region = forPostcode(postcode);
64	        return region != null ? region : forCity(city);
65	    }
66	
67	    /**
68	     * Returns the canonical region for the given city, or {@code "UNKNOWN"} when the city is not in
69	     * the fixed city-to-region table (including a {@code null} city).
70	     *
71	     * @param city the owner's stored city, or {@code null}
72	     * @return the canonical region string, or {@code "UNKNOWN"} when the city is not in the table
73	     */
74	    public static String forCity(String city) {
75	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
76	    }
77	
78	    /**
79	     * Returns the canonical region whose postcode range contains the given postcode, or
80	     * {@code null} when the postcode is absent, non-numeric, or in no known range.
81	     */
82	    private static String forPostcode(String postcode) {
83	        if (postcode == null) {
84	            return null;
85	        }
86	        int value;
87	        try {
88	            value = Integer.parseInt(postcode.trim());
89	        }
90	        catch (NumberFormatException ex) {
91	            return null;
92	        }
93	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
94	            int[] range = entry.getValue();
95	            if (value >= range[0] && value <= range[1]) {
96	                return entry.getKey();
97	            }
98	        }
99	        return null;
100	    }
101	}
