16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 format")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "postcode")
55	    private String postcode;
56	
57	    @Column(name = "registration_date")
58	    private LocalDate registrationDate;
59	
60	    @Column(name = "birth_date")
61	    private LocalDate birthDate;
62	
63	    @Column(name = "customer_code")
64	    private String customerCode;
65	
66	    @Column(name = "household_id")
67	    private String householdId;
68	
69	    @Column(name = "namesake_count")
70	    private Integer namesakeCount;
71	
72	    @Column(name = "membership_number")
73	    private String membershipNumber;
74	
75	    @Column(name = "possible_duplicate")
76	    private Boolean possibleDuplicate;
77	
78	    @Column(name = "possible_duplicate_of")
79	    private Integer possibleDuplicateOf;
80	
81	    /**
82	     * The number of owners belonging to this owner's household (owners sharing the same
83	     * {@code householdId}), including this owner. It is a derived, non-persistent value populated
84	     * when an owner is mapped for a response.
85	     */
86	    @Transient
87	    private Integer householdMemberCount;
88	
89	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
90	    private Set<Pet> pets;
91	
92	    public String getAddress() {
93	        return this.address;
94	    }
95	
96	    public void setAddress(String address) {
97	        this.address = address;
98	    }
99	
100	    public String getCity() {
101	        return this.city;
102	    }
103	
104	    public void setCity(String city) {
105	        this.city = city;
106	    }
107	
108	    public String getTelephone() {
109	        return this.telephone;
110	    }
111	
112	    public void setTelephone(String telephone) {
113	        this.telephone = telephone;
114	    }
115	
116	    /**
117	     * The known E.164 country calling codes this owner's telephone may carry, used only to split the
118	     * stored number into its country code and national digits for display. Australia ('+61') and the
119	     * North American Numbering Plan ('+1') mirror the codes the create endpoint recognises.
120	     */
121	    private static final String[] KNOWN_COUNTRY_CODES = {"61", "1"};
122	
123	    /**
124	     * The stored E.164 {@code telephone} formatted for human reading: the country calling code (kept
125	     * with its leading {@code '+'}), a space, then the national digits grouped in threes from the left
126	     * and separated by spaces (e.g. {@code +61412345678} becomes {@code "+61 412 345 678"}). The
127	     * country code is taken as the longest {@link #KNOWN_COUNTRY_CODES} match, defaulting to a
128	     * two-digit code when none is recognised. It is a derived value; the raw {@code telephone} stays in
129	     * E.164 form.
130	     *
131	     * @return the human-formatted telephone, or the raw {@code telephone} when it is {@code null} or
132	     *         not in E.164 form
133	     */
134	    public String getTelephoneDisplay() {
135	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
136	            return this.telephone;
137	        }
138	        String digits = this.telephone.substring(1);
139	        String countryCode = null;
140	        for (String code : KNOWN_COUNTRY_CODES) {
141	            if (digits.startsWith(code) && digits.length() > code.length()
142	                && (countryCode == null || code.length() > countryCode.length())) {
143	                countryCode = code;
144	            }
145	        }
146	        if (countryCode == null) {
147	            countryCode = digits.substring(0, Math.min(2, digits.length()));
148	        }
149	        String national = digits.substring(countryCode.length());
150	        StringBuilder sb = new StringBuilder("+").append(countryCode);
151	        for (int i = 0; i < national.length(); i += 3) {
152	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
153	        }
154	        return sb.toString();
155	    }
156	
157	    public String getEmail() {
158	        return this.email;
159	    }
160	
161	    public void setEmail(String email) {
162	        this.email = email;
163	    }
164	
165	    public String getPostcode() {
166	        return this.postcode;
167	    }
168	
169	    public void setPostcode(String postcode) {
170	        this.postcode = postcode;
171	    }
172	
173	    public LocalDate getRegistrationDate() {
174	        return this.registrationDate;
175	    }
176	
177	    public void setRegistrationDate(LocalDate registrationDate) {
178	        this.registrationDate = registrationDate;
179	    }
180	
181	    public LocalDate getBirthDate() {
182	        return this.birthDate;
183	    }
184	
185	    public void setBirthDate(LocalDate birthDate) {
186	        this.birthDate = birthDate;
187	    }
188	
189	    public String getCustomerCode() {
190	        return this.customerCode;
191	    }
192	
193	    public void setCustomerCode(String customerCode) {
194	        this.customerCode = customerCode;
195	    }
196	
197	    public String getHouseholdId() {
198	        return this.householdId;
199	    }
200	
201	    public void setHouseholdId(String householdId) {
202	        this.householdId = householdId;
203	    }
204	
205	    public Integer getNamesakeCount() {
206	        return this.namesakeCount;
207	    }
208	
209	    public void setNamesakeCount(Integer namesakeCount) {
210	        this.namesakeCount = namesakeCount;
211	    }
212	
213	    public String getMembershipNumber() {
214	        return this.membershipNumber;
215	    }
216	
217	    public void setMembershipNumber(String membershipNumber) {
218	        this.membershipNumber = membershipNumber;
219	    }
220	
221	    public Boolean getPossibleDuplicate() {
222	        return this.possibleDuplicate;
223	    }
224	
225	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
226	        this.possibleDuplicate = possibleDuplicate;
227	    }
228	
229	    public Integer getPossibleDuplicateOf() {
230	        return this.possibleDuplicateOf;
231	    }
232	
233	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
234	        this.possibleDuplicateOf = possibleDuplicateOf;
235	    }
236	
237	    public Integer getHouseholdMemberCount() {
238	        return this.householdMemberCount;
239	    }
240	
241	    public void setHouseholdMemberCount(Integer householdMemberCount) {
242	        this.householdMemberCount = householdMemberCount;
243	    }
244	
245	    /**
246	     * The owner's membership points, a non-negative score. It starts at 0 and accumulates: 2 points
247	     * when an email address is present, 1 point when the owner has no namesakes ({@code namesakeCount}
248	     * is zero), 2 points for a household of 3 or more members ({@code householdMemberCount} is at least
249	     * 3), and 3 points for tenure &mdash; the number of whole days from {@code registrationDate} to
250	     * today &mdash; of more than 365 days.
251	     *
252	     * @return the derived membership points (0 or more)
253	     */
254	    public Integer getMembershipPoints() {
255	        int points = 0;
256	        if (this.email != null && !this.email.isBlank()) {
257	            points += 2;
258	        }
259	        if (this.namesakeCount != null && this.namesakeCount == 0) {
260	            points += 1;
261	        }
262	        if (this.householdMemberCount != null && this.householdMemberCount >= 3) {
263	            points += 2;
264	        }
265	        if (this.registrationDate != null
266	            && java.time.temporal.ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365) {
267	            points += 3;
268	        }
269	        return points;
270	    }
271	
272	    /**
273	     * The owner's membership level, a number from 1 to 4, derived from {@link #getMembershipPoints()}:
274	     * level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and level 4 for 6 or more
275	     * points.
276	     *
277	     * @return the derived membership level (1 to 4)
278	     */
279	    public Integer getMembershipLevel() {
280	        int points = getMembershipPoints();
281	        if (points >= 6) {
282	            return 4;
283	        }
284	        if (points >= 4) {
285	            return 3;
286	        }
287	        if (points >= 2) {
288	            return 2;
289	        }
290	        return 1;
291	    }
292	
293	    /**
294	     * The Luhn check digit (0-9) computed over the digits contained in this owner's
295	     * {@code customerCode}. Non-digit characters are ignored; the rightmost digit is doubled.
296	     *
297	     * @return the single Luhn check digit, or {@code null} when there is no customer code
298	     */
299	    public Integer getCheckDigit() {
300	        if (this.customerCode == null) {
301	            return null;
302	        }
303	        int sum = 0;
304	        boolean dbl = true;
305	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
306	            char c = this.customerCode.charAt(i);
307	            if (c < '0' || c > '9') {
308	                continue;
309	            }
310	            int d = c - '0';
311	            if (dbl) {
312	                d *= 2;
313	                if (d > 9) {
314	                    d -= 9;
315	                }
316	            }
317	            sum += d;
318	            dbl = !dbl;
319	        }
320	        return (10 - (sum % 10)) % 10;
321	    }
322	
323	    /**
324	     * The owner's age band, derived from {@code birthDate} computed against {@code registrationDate}:
325	     * {@code MINOR} when the owner is under 18, {@code ADULT} from 18 to 64, and {@code SENIOR} at 65
326	     * or older. It is a derived, non-persistent value; when no {@code birthDate} is present it is
327	     * {@code null}.
328	     *
329	     * @return {@code "MINOR"}, {@code "ADULT"} or {@code "SENIOR"}, or {@code null} when no birth date
330	     *         is present
331	     */
332	    public String getAgeBand() {
333	        if (this.birthDate == null) {
334	            return null;
335	        }
336	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
337	        int age = java.time.Period.between(this.birthDate, reference).getYears();
338	        if (age < 18) {
339	            return "MINOR";
340	        }
341	        if (age < 65) {
342	            return "ADULT";
343	        }
344	        return "SENIOR";
345	    }
346	
347	    /**
348	     * The owner's preferred contact channel, derived from the stored fields: {@code EMAIL} when an
349	     * email address is present, otherwise {@code PHONE}.
350	     *
351	     * @return {@code "EMAIL"} when an email address is present, otherwise {@code "PHONE"}
352	     */
353	    public String getContactPreference() {
354	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
355	    }
356	
357	    /**
358	     * The owner's identity key: the single derived value used to detect duplicate owners. It is the
359	     * owner's normalized telephone, its email (empty when none) and its {@code householdId} (empty
360	     * when none) joined by {@code '|'}. Because the telephone is part of the key, two members of the
361	     * same household with different telephones have different identity keys; only owners whose whole
362	     * key is identical are duplicates.
363	     *
364	     * @return the {@code normalizedTelephone|email|householdId} identity key
365	     */
366	    public String getIdentityKey() {
367	        String telephonePart = this.telephone == null ? "" : this.telephone;
368	        String emailPart = this.email == null ? "" : this.email;
369	        String householdPart = this.householdId == null ? "" : this.householdId;
370	        return telephonePart + '|' + emailPart + '|' + householdPart;
371	    }
372	
373	    protected Set<Pet> getPetsInternal() {
374	        if (this.pets == null) {
375	            this.pets = new HashSet<>();
376	        }
377	        return this.pets;
378	    }
379	
380	    protected void setPetsInternal(Set<Pet> pets) {
381	        this.pets = pets;
382	    }
383	
384	    public List<Pet> getPets() {
385	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
386	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
387	        return Collections.unmodifiableList(sortedPets);
388	    }
389	
390	    public void setPets(List<Pet> pets) {
391	        this.pets = new HashSet<>(pets);
392	    }
393	
394	    public void addPet(Pet pet) {
395	        getPetsInternal().add(pet);
396	        pet.setOwner(this);
397	    }
398	
399	    /**
400	     * Return the Pet with the given name, or null if none found for this Owner.
401	     *
402	     * @param name to test
403	     * @return true if pet name is already in use
404	     */
405	    public Pet getPet(String name) {
406	        return getPet(name, false);
407	    }
408	
409	    /**
410	     * Return the Pet with the given name, or null if none found for this Owner.
411	     *
412	     * @param name to test
413	     * @return true if pet name is already in use
414	     */
415	    public Pet getPet(String name, boolean ignoreNew) {
416	        name = name.toLowerCase();
417	        for (Pet pet : getPetsInternal()) {
418	            if (!ignoreNew || !pet.isNew()) {
419	                String compName = pet.getName();
420	                compName = compName.toLowerCase();
421	                if (compName.equals(name)) {
422	                    return pet;
423	                }
424	            }
425	        }
426	        return null;
427	    }
428	
429	    public Pet getPet(Integer petId) {
430	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
431	    }
432	
433	    @Override
434	    public String toString() {
435	        return new ToStringCreator(this)
436	
437	            .append("id", this.getId())
438	            .append("new", this.isNew())
439	            .append("lastName", this.getLastName())
440	            .append("firstName", this.getFirstName())
441	            .append("address", this.address)
442	            .append("city", this.city)
443	            .append("telephone", this.telephone)
444	            .toString();
445	    }
446	}
